package com.primehr.rsp.evaluation.domain;
import com.primehr.rsp.domain.RspAuditedEntity;import com.primehr.shared.exception.IllegalLifecycleTransitionException;import jakarta.persistence.*;import org.hibernate.annotations.Nationalized;import java.time.*;import java.util.*;
@Entity @Table(name="rsp_comparative_evaluation") public class ComparativeEvaluation extends RspAuditedEntity{
 public enum Status{GENERATED,FINALIZED,SUPERSEDED}@Column(name="proceeding_id",nullable=false,length=36)private String proceedingId;@Column(name="evaluation_revision",nullable=false)private int evaluationRevision;@Column(name="supersedes_id",length=36)private String supersedesId;@Enumerated(EnumType.STRING)@Column(nullable=false,length=20)private Status status;@Column(name="current_final_key",length=36)private String currentFinalKey;@Column(name="policy_id",nullable=false,length=36)private String policyId;@Column(name="policy_definition_version",nullable=false)private int policyDefinitionVersion;@Column(name="policy_fingerprint",nullable=false,length=64)private String policyFingerprint;@Nationalized @Column(name="calculation_snapshot",nullable=false,length=32000)private String calculationSnapshot;@Column(name="calculation_fingerprint",nullable=false,length=64)private String calculationFingerprint;@Column(name="generated_by",nullable=false,length=100)private String generatedBy;@Column(name="generated_at",nullable=false)private Instant generatedAt;@Column(name="finalized_by",length=100)private String finalizedBy;@Column(name="finalized_at")private Instant finalizedAt;
 protected ComparativeEvaluation(){}public ComparativeEvaluation(String agency,String proceeding,int revision,String prior,String policy,int policyVersion,String policyFingerprint,String snapshot,String fingerprint,String actor,Instant at){super(agency);proceedingId=requiredText(proceeding,"proceedingId");if(revision<1||policyVersion<1)throw new IllegalArgumentException("Versions must be positive");evaluationRevision=revision;supersedesId=optionalText(prior);policyId=requiredText(policy,"policyId");policyDefinitionVersion=policyVersion;this.policyFingerprint=requiredText(policyFingerprint,"policyFingerprint");calculationSnapshot=requiredText(snapshot,"calculationSnapshot");calculationFingerprint=requiredText(fingerprint,"calculationFingerprint");generatedBy=requiredText(actor,"actor");generatedAt=Objects.requireNonNull(at);status=Status.GENERATED;}public void finalizeEvaluation(String actor,Instant at){if(status!=Status.GENERATED)throw new IllegalLifecycleTransitionException("Only a GENERATED comparative evaluation may be finalized");finalizedBy=requiredText(actor,"actor");finalizedAt=Objects.requireNonNull(at);currentFinalKey=proceedingId;status=Status.FINALIZED;}public void supersede(){if(status!=Status.FINALIZED)throw new IllegalLifecycleTransitionException("Only a FINALIZED comparative evaluation may be superseded");currentFinalKey=null;status=Status.SUPERSEDED;}
 public String getProceedingId(){return proceedingId;}public int getEvaluationRevision(){return evaluationRevision;}public String getSupersedesId(){return supersedesId;}public Status getStatus(){return status;}public String getPolicyId(){return policyId;}public int getPolicyDefinitionVersion(){return policyDefinitionVersion;}public String getPolicyFingerprint(){return policyFingerprint;}public String getCalculationSnapshot(){return calculationSnapshot;}public String getCalculationFingerprint(){return calculationFingerprint;}public String getGeneratedBy(){return generatedBy;}public Instant getGeneratedAt(){return generatedAt;}public String getFinalizedBy(){return finalizedBy;}public Instant getFinalizedAt(){return finalizedAt;}
}
